<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('petugas');csrf_check();$pid=(int)($_POST['petugas_id']??0);require_selected_petugas($pid);$id=(int)($_POST['id_progress']??0);$q=$pdo->prepare("SELECT ph.id_progress,ph.id_kegiatan FROM progress_harian ph JOIN petugas p ON p.id_petugas=ph.id_petugas JOIN kegiatan k ON k.id_kegiatan=ph.id_kegiatan WHERE ph.id_progress=? AND ph.id_petugas=? AND p.id_user=? AND p.deleted_at IS NULL AND k.status='aktif'");$q->execute([$id,$pid,current_user()['id_user']]);$r=$q->fetch();if(!$r){http_response_code(403);exit('Progress tidak dapat dihapus.');}$hasKwitansi=$pdo->prepare('SELECT COUNT(*) FROM kwitansi WHERE id_progress=?');$hasKwitansi->execute([$id]);if((int)$hasKwitansi->fetchColumn()){flash('danger','Progress tidak dapat dihapus karena sudah memiliki data administrasi kwitansi.');redirect('/petugas/progress/index.php?id='.$pid);}try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT d.path_file FROM dokumentasi d JOIN detail_progress x ON x.id_detail=d.id_detail WHERE x.id_progress=?');$s->execute([$id]);$files=$s->fetchAll(PDO::FETCH_COLUMN);$pdo->prepare('DELETE d FROM dokumentasi d JOIN detail_progress x ON x.id_detail=d.id_detail WHERE x.id_progress=?')->execute([$id]);$pdo->prepare('DELETE FROM detail_progress WHERE id_progress=?')->execute([$id]);$pdo->prepare('DELETE FROM progress_harian WHERE id_progress=?')->execute([$id]);$pdo->commit();foreach($files as $f){$path=__DIR__.'/../../'.ltrim($f,'/');if(is_file($path))@unlink($path);}flash('success','Progress berhasil dihapus.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Progress tidak dapat dihapus: '.$e->getMessage());}redirect('/petugas/progress/index.php?id='.$pid);
